const express = require('express');
const bodyParser = require('body-parser');
const { Scalekit } = require('@scalekit-sdk/node');
const fs = require('fs');
const path = require('path');

const app = express();
const port = 3001;
const logFilePath = '/home/user/scalekit-webhook/events.log';

// Initialize Scalekit client
// Note: The SDK typically requires env variables for initialization, 
// but we only need the webhooks part for verification.
const scalekit = new Scalekit(
  process.env.SCALEKIT_ENVIRONMENT_URL || 'https://environment.scalekit.com',
  process.env.SCALEKIT_CLIENT_ID || 'client_id',
  process.env.SCALEKIT_CLIENT_SECRET || 'client_secret'
);

// Use raw body parser to get the raw request body for signature verification
app.use(bodyParser.raw({ type: 'application/json' }));

app.post('/webhook', (req, res) => {
  const signature = req.headers['x-scalekit-signature'];
  const webhookSecret = process.env.SCALEKIT_WEBHOOK_SECRET;

  if (!signature) {
    console.error('Missing X-Scalekit-Signature header');
    return res.status(401).send('Missing signature');
  }

  if (!webhookSecret) {
    console.error('SCALEKIT_WEBHOOK_SECRET environment variable is not set');
    return res.status(500).send('Server configuration error');
  }

  try {
    // Verify the webhook signature
    // scalekit.webhooks.verifySignature(rawBody, signature, secret)
    const payload = scalekit.webhooks.verifySignature(
      req.body.toString(),
      signature,
      webhookSecret
    );

    const eventType = payload.event_type || 'unknown';

    // Log the event type to events.log
    fs.appendFileSync(logFilePath, `${eventType}\n`);

    console.log(`Successfully processed event: ${eventType}`);
    res.status(200).send('Webhook received');
  } catch (err) {
    console.error('Signature verification failed:', err.message);
    res.status(401).send('Invalid signature');
  }
});

app.listen(port, () => {
  console.log(`Scalekit webhook handler listening at http://localhost:${port}`);
});

